//! Shared no_std patch runtime and API for firmware-backed functions and
//! variables.
//!
//! Patch payloads are compiled directly by `rustc` rather than Cargo, so keep
//! this file dependency-free and include it as a module from each payload.

use core::marker::PhantomData;

pub use patch_hook_macros::{
    function_call_post_hook, function_call_pre_hook, function_entry_hook, function_offset_hook,
};

/// Continuations generated by the firmware patch builder from guarded hook
/// metadata for the selected firmware model and patch mode.
#[doc(hidden)]
pub mod __continuations {
    include!(concat!(env!("OUT_DIR"), "/continuations.rs"));
}

/// Default terminal handler for patch payloads.
///
/// This is deliberately independent of firmware services: a panic can happen
/// while a task lock, interrupt, or panel operation is already in progress.
#[panic_handler]
fn panic(_info: &core::panic::PanicInfo) -> ! {
    loop {
        core::hint::spin_loop();
    }
}

pub enum ReadOnly {}
pub enum ReadWrite {}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum EntryHookAction<T> {
    Continue(T),
    Done(T),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct FirmwareSymbol {
    address: usize,
}

/// Extract the return type from a typed firmware C function pointer. Hook
/// attributes use this to generate wrappers without making patch authors
/// repeat the firmware function's return type.
pub trait FirmwareFunctionOutput {
    type Output;
}

macro_rules! impl_firmware_function_output {
    ($($argument:ident),*) => {
        impl<$($argument,)* Output> FirmwareFunctionOutput
            for unsafe extern "C" fn($($argument),*) -> Output
        {
            type Output = Output;
        }
    };
}

impl_firmware_function_output!();
impl_firmware_function_output!(A0);
impl_firmware_function_output!(A0, A1);
impl_firmware_function_output!(A0, A1, A2);
impl_firmware_function_output!(A0, A1, A2, A3);
impl_firmware_function_output!(A0, A1, A2, A3, A4);
impl_firmware_function_output!(A0, A1, A2, A3, A4, A5);
impl_firmware_function_output!(A0, A1, A2, A3, A4, A5, A6);
impl_firmware_function_output!(A0, A1, A2, A3, A4, A5, A6, A7);

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum HookContinuationStrategy {
    Linear,
    Cbz,
    /// Re-encode displaced Thumb BL instructions in the generated
    /// continuation. Other instruction classes are copied as-is.
    RelocatedBl,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct FunctionHookSite {
    pub name: &'static str,
    pub address: u32,
    pub displaced_len: u8,
    pub guard_sha256: &'static str,
    pub continuation: HookContinuationStrategy,
    pub dynamic_dispatch: bool,
}

#[repr(C)]
pub struct FunctionHookSiteMetadata {
    pub magic: u32,
    pub address: u32,
    pub displaced_len: u16,
    pub continuation: u8,
    pub dynamic_dispatch: u8,
    pub name: [u8; 48],
    pub guard_sha256: [u8; 64],
}

pub const fn hook_name_bytes(name: &str) -> [u8; 48] {
    let source = name.as_bytes();
    let mut result = [0; 48];
    let mut index = 0;
    while index < source.len() && index < result.len() {
        result[index] = source[index];
        index += 1;
    }
    result
}

pub const fn hook_guard_bytes(sha256: &str) -> [u8; 64] {
    let source = sha256.as_bytes();
    let mut result = [0; 64];
    let mut index = 0;
    while index < source.len() && index < result.len() {
        result[index] = source[index];
        index += 1;
    }
    result
}

impl FirmwareSymbol {
    pub const unsafe fn new(address: usize) -> Self {
        Self { address }
    }

    pub const fn address(self) -> usize {
        self.address
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u32)]
pub enum OffsetHookAction {
    Continue = 0,
    Done = 1,
}

pub struct FirmwareVariable<T, Access> {
    address: usize,
    _type: PhantomData<fn() -> (T, Access)>,
}

impl<T, Access> FirmwareVariable<T, Access> {
    pub const unsafe fn new(address: usize) -> Self {
        Self {
            address,
            _type: PhantomData,
        }
    }

    pub const fn address(&self) -> usize {
        self.address
    }
}

impl<T: Copy> FirmwareVariable<T, ReadOnly> {
    /// # Safety
    /// The bound firmware must map `address` to a readable, aligned `T` for
    /// the duration of this access.
    pub unsafe fn read(&self) -> T {
        unsafe { core::ptr::read_volatile(self.address as *const T) }
    }
}

impl<T: Copy> FirmwareVariable<T, ReadWrite> {
    /// # Safety
    /// The bound firmware must map `address` to a readable, aligned `T` for
    /// the duration of this access.
    pub unsafe fn read(&self) -> T {
        unsafe { core::ptr::read_volatile(self.address as *const T) }
    }

    /// # Safety
    /// The bound firmware must map `address` to a writable, aligned `T`, and
    /// the write must be valid in the current firmware/task context.
    pub unsafe fn write(&self, value: T) {
        unsafe { core::ptr::write_volatile(self.address as *mut T, value) }
    }
}

#[macro_export]
macro_rules! firmware_functions {
    ($( $(#[$meta:meta])* $vis:vis unsafe fn $name:ident ($($arg:ident : $arg_ty:ty),* $(,)?) $(-> $result:ty,)? at $address:expr; )+) => {
        $(
            #[allow(non_snake_case)]
            #[doc(hidden)]
            $vis mod $name {
                pub type Abi = unsafe extern "C" fn($($arg_ty),*) $(-> $result)?;
                pub const ADDRESS: usize = $address;
            }

            #[allow(non_snake_case)]
            $(#[$meta])*
            $vis unsafe fn $name($($arg: $arg_ty),*) $(-> $result)? {
                let function: unsafe extern "C" fn($($arg_ty),*) $(-> $result)? =
                    unsafe { core::mem::transmute(($address) | 1usize) };
                unsafe { function($($arg),*) }
            }
        )+
    };
}

/// Declare function entries that the Patch loader can dispatch. Function
/// addresses and signatures come from the model-specific `firmware_functions!`
/// declarations; this table adds only entry-patching and guard metadata.
#[macro_export]
macro_rules! define_function_hooks {
    (
        $bindings:ident;
        $(
            $function:ident {
                displaced_len: $length:expr,
                guard_sha256: $guard:literal,
                continuation: $continuation:ident $(,)?
                dynamic_dispatch: $dynamic_dispatch:literal $(,)?
            }
        );+ $(;)?
    ) => {
        pub const FUNCTION_HOOK_SITES: &[$crate::patch_api::FunctionHookSite] = &[
            $(
                $crate::patch_api::FunctionHookSite {
                    name: stringify!($function),
                    address: (super::$bindings::$function::ADDRESS as u32) & !1,
                    displaced_len: $length,
                    guard_sha256: $guard,
                    continuation: $crate::patch_api::HookContinuationStrategy::$continuation,
                    dynamic_dispatch: $dynamic_dispatch,
                },
            )+
        ];

        #[used]
        #[unsafe(no_mangle)]
        #[unsafe(link_section = ".patch_hooks")]
        pub static __L6_FUNCTION_HOOK_SITE_METADATA: [
            $crate::patch_api::FunctionHookSiteMetadata;
            $crate::define_function_hooks!(@count $($function),+)
        ] = [
            $(
                $crate::patch_api::FunctionHookSiteMetadata {
                    magic: 0x484f_4f4b,
                    address: (super::$bindings::$function::ADDRESS as u32) & !1,
                    displaced_len: $length,
                    continuation: $crate::define_function_hooks!(@strategy $continuation),
                    dynamic_dispatch: $dynamic_dispatch as u8,
                    name: $crate::patch_api::hook_name_bytes(stringify!($function)),
                    guard_sha256: $crate::patch_api::hook_guard_bytes($guard),
                },
            )+
        ];
    };
    (@count $($function:ident),+) => { <[()]>::len(&[$($crate::define_function_hooks!(@unit $function)),+]) };
    (@unit $function:ident) => { () };
    (@strategy Linear) => { 0 };
    (@strategy Cbz) => { 1 };
    (@strategy RelocatedBl) => { 2 };
}

#[macro_export]
macro_rules! firmware_variables {
    (@parse) => {};
    (@parse $(#[$meta:meta])* $vis:vis mut $name:ident : $ty:ty, at $address:expr; $($rest:tt)*) => {
        #[allow(non_upper_case_globals)]
        $(#[$meta])*
        $vis const $name: $crate::patch_api::FirmwareVariable<$ty, $crate::patch_api::ReadWrite> =
            unsafe { $crate::patch_api::FirmwareVariable::new($address) };
        $crate::firmware_variables!(@parse $($rest)*);
    };
    (@parse $(#[$meta:meta])* $vis:vis $name:ident : $ty:ty, at $address:expr; $($rest:tt)*) => {
        #[allow(non_upper_case_globals)]
        $(#[$meta])*
        $vis const $name: $crate::patch_api::FirmwareVariable<$ty, $crate::patch_api::ReadOnly> =
            unsafe { $crate::patch_api::FirmwareVariable::new($address) };
        $crate::firmware_variables!(@parse $($rest)*);
    };
    ($($declarations:tt)*) => {
        $crate::firmware_variables!(@parse $($declarations)*);
    };
}

#[macro_export]
macro_rules! firmware_symbols {
    ($( $(#[$meta:meta])* $vis:vis $name:ident at $address:expr; )+) => {
        $(
            #[doc(hidden)]
            $vis mod $name {
                pub const ADDRESS: usize = $address;
            }

            $(#[$meta])*
            $vis const $name: $crate::patch_api::FirmwareSymbol =
                unsafe { $crate::patch_api::FirmwareSymbol::new($address) };
        )+
    };
}

#[macro_export]
macro_rules! variable_read {
    ($name:ident) => {
        $name.read()
    };
}

#[macro_export]
macro_rules! variable_write {
    ($name:ident, $value:expr) => {
        $name.write($value)
    };
}

/// Call a generated continuation other than the current hook's own
/// continuation. Most entry hooks should use `hook_continue`; this escape hatch
/// is for cross-hook calls such as dismissing one notification while another
/// hook is running. The caller must provide the real continuation ABI.
#[macro_export]
macro_rules! call_original {
    ($symbol:ident $(, $argument:expr)* $(,)?) => {{
        let address: usize = $crate::patch_api::__continuations::address(stringify!($symbol));
        let continuation: $symbol::Abi = unsafe { core::mem::transmute(address | 1usize) };
        unsafe { continuation($($argument),*) }
    }};
}
